package tomlcheck

import (
	"net/http"
	"strings"
	"testing"

	"github.com/gin-gonic/gin/binding"
)

type V struct {
	Name string `toml:"name" binding:"required"`
}

func TestTomlValidationSkipped(t *testing.T) {
	// valid TOML, but struct validation should FAIL (required field missing)
	body := "other = 1\n"
	req, _ := http.NewRequest("POST", "/", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/toml")
	var obj V
	err := binding.TOML.Bind(req, &obj)
	t.Logf("TOML.Bind err=%v obj=%+v", err, obj)

	// compare with JSON binding, which validates
	req2, _ := http.NewRequest("POST", "/", strings.NewReader(`{"other":1}`))
	req2.Header.Set("Content-Type", "application/json")
	var obj2 V
	err2 := binding.JSON.Bind(req2, &obj2)
	t.Logf("JSON.Bind err=%v obj=%+v", err2, obj2)

	if err == nil {
		t.Errorf("BUG: TOML binding skipped validation (returned nil, JSON returns %v)", err2)
	}
}
EOF
GOFLAGS=-mod=mod go test -count=1 -v -run TestTomlValidationSkipped ./... 2>&1 | tail -20

